import React from "react";
import {
  FaCalendarDay,
  FaBullseye,
  FaPiggyBank,
} from "react-icons/fa";

const DailyLimit = ({
  goalAmount = 150000,
  currentSavings = 0,
}) => {

  const today = new Date();

  // Goal deadline (example: 31 Dec 2026)
  const targetDate = new Date("2026-12-31");

  const diffTime = targetDate - today;

  const remainingDays = Math.max(
    Math.ceil(diffTime / (1000 * 60 * 60 * 24)),
    1
  );

  const remainingAmount = Math.max(
    goalAmount - currentSavings,
    0
  );

  const dailySaving = remainingAmount / remainingDays;

  return (
    <div className="bg-slate-800 rounded-3xl shadow-xl p-6 border border-slate-700 mt-8">

      {/* Heading */}
      <div className="flex items-center gap-3 mb-6">
        <FaCalendarDay className="text-3xl text-blue-400" />

        <h2 className="text-3xl font-bold text-white">
          Daily Savings Plan
        </h2>
      </div>

      {/* Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">

        {/* Remaining Goal */}
        <div className="bg-slate-700 rounded-2xl p-5 text-center">
          <FaBullseye className="text-red-400 text-3xl mx-auto mb-3" />

          <p className="text-gray-400">
            Remaining Goal
          </p>

          <h3 className="text-white text-2xl font-bold mt-2">
            ₹{remainingAmount.toLocaleString()}
          </h3>
        </div>

        {/* Remaining Days */}
        <div className="bg-slate-700 rounded-2xl p-5 text-center">
          <FaCalendarDay className="text-yellow-400 text-3xl mx-auto mb-3" />

          <p className="text-gray-400">
            Remaining Days
          </p>

          <h3 className="text-white text-2xl font-bold mt-2">
            {remainingDays}
          </h3>
        </div>

        {/* Daily Saving */}
        <div className="bg-slate-700 rounded-2xl p-5 text-center">
          <FaPiggyBank className="text-green-400 text-3xl mx-auto mb-3" />

          <p className="text-gray-400">
            Daily Saving Needed
          </p>

          <h3 className="text-green-400 text-2xl font-bold mt-2">
            ₹{dailySaving.toFixed(0)}
          </h3>
        </div>

      </div>

      {/* Suggestion */}
      <div className="mt-8 bg-slate-700 rounded-2xl p-5 border-l-4 border-green-500">

        <h3 className="text-white font-bold text-lg mb-2">
          💡 Smart Suggestion
        </h3>

        <p className="text-gray-300">
          Save at least{" "}
          <span className="text-green-400 font-bold">
            ₹{dailySaving.toFixed(0)}
          </span>{" "}
          every day to achieve your goal before the target date.
        </p>

      </div>

    </div>
  );
};

export default DailyLimit;